WITH valid_departments AS (SELECT * FROM departments WHERE (location IN ('London', 'Chiang Mai', 'Berlin') AND dept_name = 'HR') OR location IS NULL), departments_stats AS (SELECT dept_name, location, MAX(budget) - MIN(budget) AS budget_range, SUM(CASE WHEN dept_name = 'Finance' THEN budget ELSE 0 END) AS finance_budget FROM valid_departments GROUP BY dept_name, location) SELECT * FROM departments_stats WHERE budget_range > 47 ORDER BY dept_name
